# ---------------------------------------------------------------- Tables 1 and 2 (in 4.5): one record per cell
T1LEAD = 'Table 1 (honours)'
QA = 'qaa/fheq-2024/annex-d/'


def row(k, topic, dom, fheq, ad, O, T=None, E=None, q=('', '', ''), award=HON, level='fheq:6', table='Table 1', lvl=L6, ofrc='threshold', tfrc='threshold'):
    oid, tid, eid = f'4.5.b{k}.outcome', f'4.5.b{k}', f'4.5.b{k}.excellent'
    beside_o = f'{tid} and {eid}' if T else 'the honours descriptor alone (no rung cells for this row)'
    s(oid, type='outcome', rung='none', force=ofrc, level=level, appliesTo=f'graduates of the subject ({table})', addressee='learner',
      verbs=O[1], about=O[2], domain=dom, award=award, find=O[0], para=O[3], prac=O[4], ben=O[5],
      aaw=(f'Treat this as the benchmark outcome for {topic}: what a graduate will have on graduating ({table} lead-in), graded by the cells beside it, at {lvl}. '
           f'Cite it as {CITE("4.5")}, {table}, benchmark outcome column. Do not lift it into module outcomes unchanged or claim it holds at another level. '
           f'Set it beside {beside_o}, the descriptor {fheq} and the reference step spine:{level[-1]}.'),
      aad=AD(f'someone asks what the degree should leave a graduate able to do in {topic}',
             'Explain it to a student in plain words, in the second person, and to staff as a course-level outcome, then turn to the cells that grade it.',
             q[0], 'reciting the table text at length'))
    if T:
        s(tid, type='threshold', rung='threshold', force=tfrc, level=level, appliesTo=f'graduates of the subject ({table}, threshold standard)', addressee='learner',
          verbs=T[1], about=T[2], domain=dom, award=award, find=T[0], para=T[3], prac=T[4], ben=T[5],
          aaw=(f'Treat this as the threshold cell for {topic}: the minimum for the award, at {lvl}. '
               f'Cite it as {CITE("4.5")}, {table}, threshold standard. Do not present it as the typical class of degree or as a rule binding the provider. '
               f'Set it beside the outcome {oid}, the excellent cell {eid}, the descriptor {fheq} and the Annex D third-class band {QA}{ad}/3rd.'),
          aad=AD(f'a student asks what they must at least manage in {topic}, or staff check a module against the pass line',
                 'Tell a student plainly, in the second person, that this is the floor for the award; tell staff it is the threshold column.',
                 q[1], 'reading the cell aloud word for word, and letting it stand for the level most students reach'))
    if E:
        s(eid, type='excellent', rung='excellent', force='describes', level=level, appliesTo=f'graduates of the subject ({table}, excellent standard)', addressee='learner',
          verbs=E[1], about=E[2], domain=dom, award=award, find=E[0], para=E[3], prac=E[4], ben=E[5],
          aaw=(f'Treat this as the excellent cell for {topic}: the level the statement ties to a first-class result, an aspiration and not a requirement, at {lvl}. '
               f'Cite it as {CITE("4.5")}, {table}, excellent standard. Do not describe it as the pass standard or as what most graduates reach. '
               f'Set it beside the threshold cell {tid}, which it grades upward, the descriptor {fheq} and the Annex D first-class band {QA}{ad}/1st.'),
          aad=AD(f'a student aiming high asks what top work in {topic} looks like, or staff calibrate top marks',
                 'Put it as what the strongest work shows, not as a demand; for staff, frame it as the top of the range.',
                 q[2], 'presenting it as the minimum or as the level every student must hit'))


